root_bg_06080a_bg2_0d1117_bg3_12181f:
:root{
  --bg:#06080a;
  --bg2:#0d1117;
  --bg3:#12181f;
  --gold:#c9a44e;
  --gold2:#e8c87a;
  --rose:#d98fa0;
  --green:#5a9e7a;
  --cream:#f0e6d3;
  --muted:rgba(240,230,211,0.45);
  --border:rgba(201,164,78,0.12);
  --border2:rgba(201,164,78,0.22);
}
*{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth}
body{font-family:'Nunito',sans-serif;background:var(--bg);color:var(--cream);overflow-x:hidden;cursor:default}
::-webkit-scrollbar{width:4px}
::-webkit-scrollbar-track{background:var(--bg)}
::-webkit-scrollbar-thumb{background:var(--gold);border-radius:4px}

/* PARTICLES */
#particles{position:fixed;inset:0;pointer-events:none;z-index:0;overflow:hidden}
.particle{position:absolute;border-radius:50%;animation:float linear infinite;opacity:0}
@keyframes float{
  0%{transform:translateY(100vh) scale(0);opacity:0}
  10%{opacity:1}
  90%{opacity:1}
  100%{transform:translateY(-20px) scale(1);opacity:0}
}

/* NAV */
nav{position:fixed;top:0;left:0;right:0;z-index:100;padding:0 40px;height:68px;display:flex;align-items:center;justify-content:space-between;background:rgba(6,8,10,0.85);backdrop-filter:blur(20px);border-bottom:1px solid var(--border);transition:all .3s}
.nav-logo{font-family:'Cormorant Garamond',serif;font-size:22px;font-weight:600;color:var(--gold2);letter-spacing:1px;text-decoration:none;display:flex;align-items:center;gap:10px}
.nav-logo svg{width:28px;height:28px}
.nav-links{display:flex;gap:8px;align-items:center}
.nav-links a{color:var(--muted);text-decoration:none;font-size:13.5px;font-weight:500;padding:8px 16px;border-radius:8px;transition:all .25s;letter-spacing:0.3px}
.nav-links a:hover,.nav-links a.active{color:var(--cream);background:var(--border)}
.nav-cta{background:linear-gradient(135deg,#c9a44e,#e8c87a);color:#1a1000!important;border-radius:10px!important;font-weight:700!important;padding:9px 20px!important}
.nav-cta:hover{box-shadow:0 4px 20px rgba(201,164,78,0.35);transform:translateY(-1px)}
.hamburger{display:none;flex-direction:column;gap:5px;cursor:pointer;padding:8px}
.hamburger span{width:22px;height:2px;background:var(--cream);border-radius:2px;transition:all .3s}

/* PAGES */
.page{display:none;min-height:100vh;padding-top:68px}
.page.active{display:block}

/* HERO */
#hero{position:relative;min-height:100vh;display:flex;align-items:center;justify-content:center;overflow:hidden;padding:80px 40px 40px}
.hero-bg{position:absolute;inset:0;background:radial-gradient(ellipse 80% 60% at 50% 0%,rgba(201,164,78,0.07) 0%,transparent 60%),radial-gradient(ellipse 60% 40% at 80% 80%,rgba(217,143,160,0.05) 0%,transparent 50%),radial-gradient(ellipse 40% 40% at 20% 70%,rgba(90,158,122,0.05) 0%,transparent 50%)}
.hero-content{position:relative;z-index:2;text-align:center;max-width:800px}
.hero-badge{display:inline-flex;align-items:center;gap:8px;padding:8px 20px;border-radius:100px;border:1px solid var(--border2);background:rgba(201,164,78,0.06);font-size:12px;font-weight:600;letter-spacing:2.5px;text-transform:uppercase;color:var(--gold);margin-bottom:28px;animation:fadeUp .8s ease both}
.hero-badge::before{content:'✦';font-size:10px}
.hero-badge::after{content:'✦';font-size:10px}
h1.hero-title{font-family:'Cormorant Garamond',serif;font-size:clamp(3rem,8vw,6rem);font-weight:300;line-height:1.05;letter-spacing:-1px;animation:fadeUp .8s .15s ease both}
h1.hero-title em{font-style:italic;background:linear-gradient(135deg,var(--gold),var(--gold2));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.hero-sub{font-size:16px;line-height:1.7;color:var(--muted);max-width:520px;margin:24px auto 40px;animation:fadeUp .8s .3s ease both;font-weight:300}
.hero-btns{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;animation:fadeUp .8s .45s ease both}
.btn-primary{display:inline-flex;align-items:center;gap:10px;padding:14px 32px;border-radius:14px;background:linear-gradient(135deg,#c9a44e,#e8c87a);color:#1a1000;font-weight:700;font-size:14px;text-decoration:none;transition:all .3s;border:none;cursor:pointer}
.btn-primary:hover{box-shadow:0 8px 30px rgba(201,164,78,0.4);transform:translateY(-2px)}
.btn-secondary{display:inline-flex;align-items:center;gap:10px;padding:14px 32px;border-radius:14px;background:transparent;color:var(--cream);font-weight:600;font-size:14px;text-decoration:none;transition:all .3s;border:1px solid var(--border2);cursor:pointer}
.btn-secondary:hover{background:rgba(255,255,255,0.04);border-color:rgba(201,164,78,0.35)}
.hero-stats{display:flex;gap:48px;justify-content:center;margin-top:64px;animation:fadeUp .8s .6s ease both}
.stat{text-align:center}
.stat-num{font-family:'Cormorant Garamond',serif;font-size:36px;font-weight:600;color:var(--gold2);line-height:1}
.stat-label{font-size:11px;letter-spacing:2px;text-transform:uppercase;color:var(--muted);margin-top:4px}
.hero-divider{display:flex;align-items:center;gap:16px;margin-top:60px;animation:fadeUp .8s .75s ease both;color:var(--muted);font-size:12px;letter-spacing:2px;text-transform:uppercase}
.hero-divider::before,.hero-divider::after{content:'';flex:1;height:1px;background:linear-gradient(90deg,transparent,var(--border2))}
.hero-divider::after{background:linear-gradient(270deg,transparent,var(--border2))}
.scrollhint{position:absolute;bottom:32px;left:50%;transform:translateX(-50%);animation:bounce 2s infinite;cursor:pointer}
.scrollhint svg{width:24px;height:24px;color:var(--gold);opacity:.5}
@keyframes bounce{0%,100%{transform:translateX(-50%) translateY(0)}50%{transform:translateX(-50%) translateY(8px)}}

/* FEATURED CATEGORIES */
.section{padding:100px 40px}
.section-inner{max-width:1140px;margin:0 auto}
.section-label{font-size:11px;letter-spacing:3px;text-transform:uppercase;color:var(--gold);font-weight:700;margin-bottom:12px;display:block}
.section-title{font-family:'Cormorant Garamond',serif;font-size:clamp(2rem,5vw,3.2rem);font-weight:400;line-height:1.15;margin-bottom:16px}
.section-sub{color:var(--muted);font-size:15px;line-height:1.7;max-width:520px;font-weight:300}
.cat-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:20px;margin-top:56px}
.cat-card{background:var(--bg2);border:1px solid var(--border);border-radius:20px;overflow:hidden;cursor:pointer;transition:all .4s;position:relative;group}
.cat-card:hover{transform:translateY(-6px);border-color:var(--border2);box-shadow:0 20px 60px rgba(0,0,0,0.5)}
.cat-img{width:100%;aspect-ratio:1;object-fit:cover;display:block;transition:transform .5s;filter:brightness(0.9) saturate(1.1)}
.cat-card:hover .cat-img{transform:scale(1.05);filter:brightness(1) saturate(1.2)}
.cat-img-placeholder{width:100%;aspect-ratio:1;display:flex;align-items:center;justify-content:center;font-size:80px;background:var(--bg3)}
.cat-body{padding:24px}
.cat-icon{font-size:28px;margin-bottom:10px}
.cat-name{font-family:'Cormorant Garamond',serif;font-size:22px;font-weight:600;margin-bottom:6px}
.cat-desc{font-size:13px;color:var(--muted);line-height:1.6;margin-bottom:16px;font-weight:300}
.cat-price{font-size:13px;font-weight:700;color:var(--gold);display:flex;align-items:center;gap:6px}
.cat-price-from{font-size:11px;color:var(--muted);font-weight:400}
.cat-badge{position:absolute;top:16px;right:16px;background:rgba(201,164,78,0.9);color:#1a1000;font-size:10px;font-weight:800;letter-spacing:1.5px;text-transform:uppercase;padding:5px 12px;border-radius:20px}

/* CATALOG PAGE */
.catalog-header{padding:60px 40px 40px;text-align:center}
.filter-bar{display:flex;gap:10px;flex-wrap:wrap;justify-content:center;margin:32px 0}
.filter-btn{padding:9px 22px;border-radius:100px;border:1px solid var(--border);background:transparent;color:var(--muted);font-size:13px;font-weight:600;cursor:pointer;transition:all .3s;font-family:'Nunito',sans-serif;letter-spacing:0.3px}
.filter-btn:hover,.filter-btn.active{background:var(--gold);border-color:var(--gold);color:#1a1000}
.products-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:24px;padding:0 40px 80px;max-width:1200px;margin:0 auto}
.prod-card{background:var(--bg2);border:1px solid var(--border);border-radius:20px;overflow:hidden;transition:all .4s;position:relative}
.prod-card:hover{transform:translateY(-5px);border-color:var(--border2);box-shadow:0 16px 50px rgba(0,0,0,0.4)}
.prod-card.hidden{display:none}
.prod-img{width:100%;aspect-ratio:4/5;object-fit:cover;object-position:center top;filter:brightness(0.92) saturate(1.15) contrast(1.05)}
.prod-card:hover .prod-img{filter:brightness(1.02) saturate(1.25) contrast(1.08)}
.prod-img-wrap{position:relative;overflow:hidden}
.prod-badge-occasion{position:absolute;top:14px;left:14px;padding:5px 14px;border-radius:100px;font-size:10px;font-weight:800;letter-spacing:1.5px;text-transform:uppercase;backdrop-filter:blur(8px)}
.badge-bautizo{background:rgba(90,158,122,0.85);color:#fff}
.badge-comunion{background:rgba(255,255,255,0.85);color:#1a1000}
.badge-navidad{background:rgba(197,50,50,0.85);color:#fff}
.badge-jardin{background:rgba(90,140,80,0.85);color:#fff}
.badge-hadas{background:rgba(217,143,160,0.85);color:#1a1000}
.badge-personalizado{background:rgba(201,164,78,0.85);color:#1a1000}
.prod-fav{position:absolute;top:14px;right:14px;width:34px;height:34px;border-radius:50%;background:rgba(6,8,10,0.7);backdrop-filter:blur(8px);display:flex;align-items:center;justify-content:center;cursor:pointer;transition:all .3s;border:1px solid var(--border);font-size:16px}
.prod-fav:hover{background:rgba(201,164,78,0.2);border-color:var(--gold)}
.prod-info{padding:20px 22px 22px}
.prod-occasion{font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--gold);font-weight:700;margin-bottom:6px}
.prod-name{font-family:'Cormorant Garamond',serif;font-size:20px;font-weight:600;line-height:1.2;margin-bottom:8px}
.prod-desc{font-size:12.5px;color:var(--muted);line-height:1.6;margin-bottom:16px;font-weight:300}
.prod-footer{display:flex;align-items:center;justify-content:space-between;gap:12px}
.prod-price{font-family:'Cormorant Garamond',serif;font-size:26px;font-weight:600;color:var(--gold2)}
.prod-price small{font-size:13px;font-family:'Nunito',sans-serif;color:var(--muted);font-weight:400}
.btn-wa{display:inline-flex;align-items:center;gap:6px;padding:9px 18px;border-radius:10px;background:#25D366;color:#fff;font-size:12px;font-weight:700;text-decoration:none;transition:all .3s}
.btn-wa:hover{background:#1db954;box-shadow:0 4px 16px rgba(37,211,102,0.35);transform:scale(1.03)}

/* OCCASIONS STRIP */
.occasions{background:var(--bg2);border-top:1px solid var(--border);border-bottom:1px solid var(--border);padding:48px 40px}
.occasions-inner{max-width:1140px;margin:0 auto}
.occ-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:16px;margin-top:32px}
.occ-item{text-align:center;padding:24px 16px;border-radius:16px;border:1px solid var(--border);background:var(--bg3);transition:all .3s;cursor:pointer}
.occ-item:hover{border-color:var(--border2);background:rgba(201,164,78,0.05);transform:translateY(-3px)}
.occ-emoji{font-size:36px;margin-bottom:10px}
.occ-name{font-size:13px;font-weight:600;margin-bottom:4px}
.occ-price{font-size:11px;color:var(--gold);font-weight:700}

/* ABOUT */
.about-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center;max-width:1100px;margin:0 auto;padding:100px 40px}
.about-img-area{position:relative}
.about-img-frame{width:100%;aspect-ratio:3/4;border-radius:24px;overflow:hidden;border:1px solid var(--border);position:relative}
.about-img-frame img{width:100%;height:100%;object-fit:cover;filter:brightness(0.9) saturate(1.1)}
.about-accent{position:absolute;bottom:-20px;right:-20px;width:140px;height:140px;border-radius:16px;background:var(--bg2);border:1px solid var(--border2);display:flex;align-items:center;justify-content:center;flex-direction:column;gap:4px;font-family:'Cormorant Garamond',serif}
.about-accent-num{font-size:42px;font-weight:600;color:var(--gold2);line-height:1}
.about-accent-label{font-size:11px;color:var(--muted);letter-spacing:1px;text-align:center}
.about-content{}
.features{display:flex;flex-direction:column;gap:20px;margin-top:40px}
.feature{display:flex;gap:16px;align-items:flex-start}
.feature-icon{width:44px;height:44px;border-radius:12px;background:rgba(201,164,78,0.08);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0}
.feature-title{font-size:14px;font-weight:700;margin-bottom:3px}
.feature-desc{font-size:13px;color:var(--muted);line-height:1.6;font-weight:300}
.process-steps{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:24px;margin-top:56px}
.step{background:var(--bg2);border:1px solid var(--border);border-radius:16px;padding:28px 24px;position:relative}
.step-num{position:absolute;top:-14px;left:24px;width:28px;height:28px;border-radius:8px;background:var(--gold);color:#1a1000;font-size:12px;font-weight:800;display:flex;align-items:center;justify-content:center}
.step-icon{font-size:32px;margin-bottom:14px;margin-top:4px}
.step-title{font-size:14px;font-weight:700;margin-bottom:6px}
.step-desc{font-size:12.5px;color:var(--muted);line-height:1.6;font-weight:300}

/* CONTACT */
.contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:60px;max-width:1100px;margin:0 auto;padding:0 40px 80px;align-items:start}
.contact-info{}
.contact-cards{display:flex;flex-direction:column;gap:16px;margin-top:40px}
.contact-card{background:var(--bg2);border:1px solid var(--border);border-radius:16px;padding:22px;display:flex;align-items:flex-start;gap:16px;transition:all .3s}
.contact-card:hover{border-color:var(--border2);transform:translateX(4px)}
.contact-card-icon{width:44px;height:44px;border-radius:12px;background:rgba(201,164,78,0.08);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0}
.contact-card-title{font-size:12px;letter-spacing:1px;text-transform:uppercase;color:var(--gold);font-weight:700;margin-bottom:4px}
.contact-card-val{font-size:14px;font-weight:500;margin-bottom:4px}
.contact-card-link{font-size:12px;color:var(--muted);text-decoration:none;transition:color .2s}
.contact-card-link:hover{color:var(--gold)}
.wa-big{display:flex;align-items:center;gap:12px;padding:20px 28px;border-radius:16px;background:linear-gradient(135deg,#128C7E,#25D366);color:#fff;font-size:16px;font-weight:700;text-decoration:none;transition:all .3s;justify-content:center;margin-top:24px}
.wa-big:hover{transform:scale(1.02);box-shadow:0 8px 32px rgba(37,211,102,0.4)}
.contact-form-area{background:var(--bg2);border:1px solid var(--border);border-radius:24px;padding:40px}
.form-title{font-family:'Cormorant Garamond',serif;font-size:26px;font-weight:500;margin-bottom:8px}
.form-sub{font-size:13px;color:var(--muted);margin-bottom:32px;font-weight:300}
.form-group{margin-bottom:20px}
.form-label{display:block;font-size:12px;font-weight:600;letter-spacing:1px;text-transform:uppercase;color:var(--muted);margin-bottom:8px}
.form-input{width:100%;padding:13px 16px;border-radius:12px;border:1px solid var(--border);background:var(--bg3);color:var(--cream);font-size:14px;font-family:'Nunito',sans-serif;transition:all .3s;outline:none}
.form-input:focus{border-color:var(--border2);box-shadow:0 0 0 3px rgba(201,164,78,0.08)}
.form-input::placeholder{color:rgba(240,230,211,0.25)}
textarea.form-input{resize:vertical;min-height:120px}
select.form-input option{background:var(--bg3)}
.form-send{width:100%;padding:15px;border-radius:12px;background:linear-gradient(135deg,#c9a44e,#e8c87a);color:#1a1000;font-weight:800;font-size:14px;border:none;cursor:pointer;transition:all .3s;font-family:'Nunito',sans-serif;letter-spacing:0.5px}
.form-send:hover{box-shadow:0 6px 25px rgba(201,164,78,0.4);transform:translateY(-1px)}

/* GALLERY */
.gallery-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:16px;padding:0 40px 80px;max-width:1200px;margin:0 auto}
.gal-item{border-radius:16px;overflow:hidden;aspect-ratio:1;cursor:pointer;position:relative;border:1px solid var(--border);transition:all .4s}
.gal-item:hover{transform:scale(1.02);border-color:var(--border2);box-shadow:0 12px 40px rgba(0,0,0,0.5)}
.gal-item img{width:100%;height:100%;object-fit:cover;object-position:center top;filter:brightness(0.9) saturate(1.1) contrast(1.05);transition:all .4s}
.gal-item:hover img{filter:brightness(1.05) saturate(1.3) contrast(1.08);transform:scale(1.08)}
.gal-item:first-child,.gal-item:nth-child(5){grid-column:span 2}

/* FOOTER */
footer{background:var(--bg2);border-top:1px solid var(--border);padding:60px 40px 40px}
.footer-inner{max-width:1140px;margin:0 auto;display:grid;grid-template-columns:2fr 1fr 1fr;gap:60px}
.footer-brand .brand-name{font-family:'Cormorant Garamond',serif;font-size:28px;font-weight:500;color:var(--gold2);margin-bottom:12px}
.footer-brand p{font-size:13px;color:var(--muted);line-height:1.7;max-width:280px;font-weight:300}
.footer-col h4{font-size:12px;letter-spacing:2px;text-transform:uppercase;color:var(--gold);font-weight:700;margin-bottom:20px}
.footer-col a{display:block;color:var(--muted);text-decoration:none;font-size:13px;margin-bottom:10px;transition:color .2s;font-weight:300}
.footer-col a:hover{color:var(--cream)}
.footer-bottom{max-width:1140px;margin:40px auto 0;padding-top:24px;border-top:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;font-size:12px;color:rgba(240,230,211,0.25)}
.social-links{display:flex;gap:12px}
.social-link{width:36px;height:36px;border-radius:10px;background:var(--bg3);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;text-decoration:none;transition:all .3s;font-size:16px}
.social-link:hover{border-color:var(--border2);background:rgba(201,164,78,0.08);transform:translateY(-2px)}

/* WHATSAPP FLOAT */
.wa-float{position:fixed;bottom:28px;right:28px;z-index:200;width:58px;height:58px;border-radius:50%;background:#25D366;display:flex;align-items:center;justify-content:center;box-shadow:0 4px 24px rgba(37,211,102,0.5);cursor:pointer;transition:all .3s;text-decoration:none;animation:waPulse 3s infinite}
.wa-float:hover{transform:scale(1.12)}
@keyframes waPulse{0%,100%{box-shadow:0 4px 24px rgba(37,211,102,0.5)}50%{box-shadow:0 4px 40px rgba(37,211,102,0.7),0 0 0 12px rgba(37,211,102,0.08)}}

/* MOBILE NAV */
.mobile-menu{position:fixed;top:68px;left:0;right:0;background:rgba(6,8,10,0.98);backdrop-filter:blur(20px);border-bottom:1px solid var(--border);padding:20px;z-index:99;display:none;flex-direction:column;gap:8px}
.mobile-menu.open{display:flex}
.mobile-menu a{color:var(--muted);text-decoration:none;font-size:15px;font-weight:500;padding:12px 16px;border-radius:10px;transition:all .25s}
.mobile-menu a:hover,.mobile-menu a.active{color:var(--cream);background:var(--border)}

/* ANIMATIONS */
@keyframes fadeUp{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:translateY(0)}}
.fade-in{opacity:0;transform:translateY(20px);transition:opacity .6s ease,transform .6s ease}
.fade-in.visible{opacity:1;transform:translateY(0)}

/* RESPONSIVE */
@media(max-width:900px){
  nav{padding:0 20px}
  .nav-links{display:none}
  .hamburger{display:flex}
  .about-grid{grid-template-columns:1fr;padding:60px 20px}
  .contact-grid{grid-template-columns:1fr;padding:0 20px 60px}
  .footer-inner{grid-template-columns:1fr;gap:36px}
  .section{padding:60px 20px}
  .products-grid{padding:0 20px 60px}
  .gallery-grid{padding:0 20px 60px}
  .gal-item:first-child,.gal-item:nth-child(5){grid-column:span 1}
  .occasions{padding:40px 20px}
}
@media(max-width:600px){
  #hero{padding:60px 20px 40px}
  .hero-stats{gap:24px}
  .hero-stats .stat-num{font-size:28px}
  .cat-grid{grid-template-columns:1fr}
  .occ-grid{grid-template-columns:repeat(2,1fr)}
  .catalog-header{padding:40px 20px 20px}
  .filter-bar{padding:0 20px}
  .products-grid{padding:0 20px 60px;grid-template-columns:1fr}
}
